import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const view = (status: string, task0: string, task1: string, processed = 0, retried0 = false, retried1 = false) => ({ status, task0, task1, retried0, retried1, processed });

test('initial state', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nope'), null);
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  assert.equal((await h.cancel()).ok, false);
});

test('start sends Assign and both complete, counting items', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned'));
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) { assert.equal(m.from, 'run'); assert.equal(m.action, 'Assign'); assert.deepEqual(m.data, {}); }
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.equal((await h.workDone('worker0', 0)).ok, false);
  assert.equal((await h.workDone('worker0', 3)).ok, false);
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0', 2), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual({ from: r.from, to: r.to, action: r.action, data: r.data }, { from: 'worker0', to: 'run', action: 'Report', data: { task: 0, outcome: 'completed', items: 2 } });
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned', 2));
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', 3));
});

test('first failure is retried, second is recorded', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0');
  const [r] = await h.inFlight();
  assert.deepEqual(r.data, { task: 0, outcome: 'failed', items: 0 });
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned', 0, true));
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workFailed('worker0'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned', 0, true));
  await h.workDone('worker1', 2); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'completed', 2, true));
});

test('retry then success completes', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  await h.workDone('worker1', 1); await h.workDone('worker0', 1); await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', 2, false, true));
});

test('failure while cancelling is recorded, not retried', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'cancelled'));
});

test('cancel only aborts the assigned task', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0', 1); await h.deliverAll();
  assert.deepEqual(await h.cancel(), { ok: true });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.to, m.action]), [['worker1', 'Abort']]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('cancelled', 'completed', 'cancelled', 1));
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('timeout fails the task, aborts the worker, ignores the late report and its items', async () => {
  const h = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start(); await h.deliverAll();
  assert.equal((await h.taskTimeout(2)).ok, false);
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.equal((await h.taskTimeout(0)).ok, false);
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned'));
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.to, m.action]), [['worker0', 'Abort']]);
  await h.workDone('worker0', 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  await h.workDone('worker1', 1); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'completed', 1));
});

test('timeout while cancelling ends the run as failed', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0', 2); await h.deliverAll();
  await h.cancel();
  assert.deepEqual(await h.taskTimeout(1), { ok: true });
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed', 2));
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed', 2));
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('cancel before Assign arrives: Abort ignored, then Assign makes busy', async () => {
  const h = await createHost();
  await h.start();
  await h.cancel();
  assert.deepEqual(await h.run(), view('cancelling', 'assigned', 'assigned'));
  for (const m of await h.inFlight()) if (m.action === 'Abort') await h.deliver(m.id);
  for (const m of await h.inFlight()) await h.deliver(m.id);
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workDone('worker0', 1); await h.workDone('worker1', 2); await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', 3));
});

